#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT_LEN 1024
#define MAX_NORMALISED (MAX_INPUT_LEN + 1)

int main(int argc, char *argv[])
{
    const char *msg_palindrome = "PALINDROME";
    const char *msg_not_palindrome = "NOT_PALINDROME";
    const char *msg_too_long = "TOO_LONG";

    const char *input = "";
    if (argc > 1) {
        input = argv[1];
    }

    size_t input_len = strlen(input);
    if (input_len > MAX_INPUT_LEN) {
        puts(msg_too_long);
        return 0;
    }

    char normalised[MAX_NORMALISED];
    size_t n = 0;
    for (size_t i = 0; i < input_len; ++i) {
        unsigned char ch = (unsigned char)input[i];
        if (isalnum(ch)) {
            normalised[n++] = (char)tolower(ch);
        }
    }
    normalised[n] = '\0';

    int is_palindrome = 1;
    for (size_t i = 0, j = n ? n - 1 : 0; i < j; ++i, --j) {
        if (normalised[i] != normalised[j]) {
            is_palindrome = 0;
            break;
        }
    }

    puts(is_palindrome ? msg_palindrome : msg_not_palindrome);
    return 0;
}
